var filter=new UnityEngine.AI.NavMeshQueryFilter{agentTypeID=-1372625422,areaMask=-1};return UnityEngine.Object.FindObjectsOfType<TowerSlot>().OrderBy(s=>s.name).Select(s=>{UnityEngine.AI.NavMeshHit h;UnityEngine.AI.NavMesh.SamplePosition(s.transform.position,out h,15,filter);return new{name=s.name,distance=Vector3.Distance(s.transform.position,h.position),point=h.position.ToString()};}).ToArray();
